# Generated by scripts/homebrew-formulas.py in tinhthanh/shipyard for v0.3.31-fork.3.
class Vetgo < Formula
  desc "Run coding agents on your own boxes: the berth CLI and laptop agent"
  homepage "https://github.com/tinhthanh/shipyard"
  version "0.3.31-fork.3"
  license "MIT"

  on_macos do
    on_arm do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.3/berth-darwin-arm64.tar.gz"
      sha256 "981a6bcbc951387e76d1bad863624eff2b6a3c495a8c86a1436f9b2cf50a6a88"
    end
    on_intel do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.3/berth-darwin-amd64.tar.gz"
      sha256 "709e1a92d3eb9ae4f0d788994bb1002e22d8027b5ce70fb9dd0e2b12b35bf526"
    end
  end
  on_linux do
    on_arm do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.3/berth-linux-arm64.tar.gz"
      sha256 "142749197d838ba73eddd4877dc5bedacc78a64cfe1bf947d62edd853454d9fa"
    end
    on_intel do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.3/berth-linux-amd64.tar.gz"
      sha256 "5b41c1ef87e2f94032dcdc8a1e809f0b8d948b18d6c6b642a2b75fb025851f09"
    end
  end

  # The berthd builds `berth upgrade` puts on Mac boxes; the Linux ones come
  # in berth's own archive.
  on_macos do
    resource "berthd-darwin-arm64" do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.3/berthd-darwin-arm64.tar.gz"
      sha256 "1db5fed634fd2cd1887bb2a5c7bfcb2cf21dc67a8aa0e5d18bae28054276a3c4"
    end
    resource "berthd-darwin-amd64" do
      url "https://github.com/tinhthanh/shipyard/releases/download/v0.3.31-fork.3/berthd-darwin-amd64.tar.gz"
      sha256 "7a97e827de17f9ac6c1eb7ff20d304f486e58d499d579e7ef09372da6f55fdd9"
    end
  end

  def install
    # berth looks beside its own file (through the link in bin) for the
    # berthd and tmux builds it uploads to boxes.
    libexec.install Dir["*"]
    if OS.mac?
      %w[arm64 amd64].each do |arch|
        resource("berthd-darwin-#{arch}").stage { libexec.install "berthd" => "berthd-darwin-#{arch}" }
      end
    end
    bin.install_symlink libexec/"berth"
  end

  def caveats
    <<~EOS
      Start the laptop agent, and have it start when you log in:
        berth agent install
      Add a box: berth add ssh USER@HOST (see berth help).
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/berth version")
  end
end
